import { MakeLogicType, afterMount, connect, kea, listeners, path, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import api from 'lib/api'
import { organizationLogic } from 'scenes/organizationLogic'

/** Mirrors `Organization.DeactivationReason.UNPAID_INVOICE` in `posthog/models/organization.py`. */
export const UNPAID_INVOICE_REASON = 'Access paused until your unpaid invoice is paid.'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface organizationDeactivatedLogicValues {
    isNotActiveReason: string | null // organizationLogic
    isPausedForUnpaidInvoice: boolean
    unpaidInvoiceLink: string | null
    unpaidInvoiceLinkLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface organizationDeactivatedLogicActions {
    loadCurrentOrganizationSuccess: (
        currentOrganization: null | import('../../types').OrganizationType,
        payload?: any
    ) => {
        currentOrganization: null | import('../../types').OrganizationType
        payload?: any
    } // organizationLogic
    loadUnpaidInvoiceLink: () => any
    loadUnpaidInvoiceLinkFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadUnpaidInvoiceLinkSuccess: (
        unpaidInvoiceLink: string | null,
        payload?: any
    ) => {
        unpaidInvoiceLink: string | null
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface organizationDeactivatedLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        isPausedForUnpaidInvoice: (isNotActiveReason: any) => boolean
    }
}

export type organizationDeactivatedLogicType = MakeLogicType<
    organizationDeactivatedLogicValues,
    organizationDeactivatedLogicActions,
    Record<string, any>,
    organizationDeactivatedLogicMeta
>

export const organizationDeactivatedLogic = kea<organizationDeactivatedLogicType>([
    path(['scenes', 'organization', 'organizationDeactivatedLogic']),
    connect(() => ({
        values: [organizationLogic, ['isNotActiveReason']],
        actions: [organizationLogic, ['loadCurrentOrganizationSuccess']],
    })),
    loaders({
        unpaidInvoiceLink: [
            null as string | null,
            {
                loadUnpaidInvoiceLink: async (): Promise<string | null> => {
                    try {
                        // nosemgrep: prefer-codegen-api -- billingGetInvoicesRetrieve() returns void, because the endpoint's OpenAPI schema does not describe its response yet.
                        const response = await api.get('api/billing/get_invoices?status=uncollectible')
                        // Billing links the first invoice's hosted payment page, which is the one that paused access.
                        return response?.link ?? null
                    } catch {
                        // The page still offers billing, so a failed lookup only loses the shortcut.
                        return null
                    }
                },
            },
        ],
    }),
    selectors({
        isPausedForUnpaidInvoice: [
            (s) => [s.isNotActiveReason],
            (isNotActiveReason: string | null): boolean => isNotActiveReason === UNPAID_INVOICE_REASON,
        ],
    }),
    listeners(({ actions, values }) => ({
        loadCurrentOrganizationSuccess: () => {
            if (values.isPausedForUnpaidInvoice) {
                actions.loadUnpaidInvoiceLink()
            }
        },
    })),
    afterMount(({ actions, values }) => {
        if (values.isPausedForUnpaidInvoice) {
            actions.loadUnpaidInvoiceLink()
        }
    }),
])
